          console.log(`当前部分: ${this.NowSectionId}`);
        }
      });
    },
    handleScroll() {
      const sections = [
        { id: 'section1', offsetTop: document.getElementById('section1').offsetTop },
        { id: 'section2', offsetTop: document.getElementById('section2').offsetTop },
        { id: 'section3', offsetTop: document.getElementById('section3').offsetTop }
      ];

      const scrollPosition = window.scrollY + window.innerHeight / 2;

      for (let i = sections.length - 1; i >= 0; i--) {
        if (scrollPosition >= sections[i].offsetTop) {
          this.NowSectionId = sections[i].id;
          break;
        }
      }
    }
  },
  mounted() {
    window.addEventListener('scroll', this.handleScroll);
  },
  beforeDestroy() {
    window.removeEventListener('scroll', this.handleScroll);
