<template>
  <div class="login-container" style="width: 100%; height: 100%">
    <div class="background-overlay"></div>
    <el-card class="login-card" shadow="hover">
      <h2 class="login-title">后台管理</h2>
      <el-form :model="loginForm" @submit.native.prevent="handleLogin">
        <el-form-item prop="username">
          <el-input
            v-model="loginForm.username"
            placeholder="Username"
          ></el-input>
        </el-form-item>
        <el-form-item prop="password">
          <el-input
            v-model="loginForm.password"
            type="password"
            placeholder="Password"
          ></el-input>
        </el-form-item>
        <el-form-item>
          <el-button type="primary" @click="handleLogin" :loading="loading"
            >登录</el-button
          >
        </el-form-item>
      </el-form>
    </el-card>
  </div>
</template>

<script>
export default {
  data() {
    return {
      loginForm: {
        username: "",
        password: "",
      },
      loading: false,
    };
  },
  methods: {
    handleLogin() {
      this.axios({
        method: "get",
        url: "http://106.54.28.250:8093/user/user/login",
        params: {
          username: this.loginForm.username,
          password: this.loginForm.password,
        },
      }).then((respons) => {
        if (respons.data.code === 301) {
          this.$message.error("密码错误");
        } else {
          console.log("登录成功的res",respons.headers);
          this.$message.success("登录成功");
          localStorage.setItem("token", respons.headers.token);
          // localStorage.setItem("userId", response.data.data.id);
          // localStorage.setItem("level", response.data.data.role);
      
        }
        this.$router.push("/ControlNews"); // 登录成功后跳转到主页或其他页面
      });
    },
  },
};
</script>

<style scoped>
.login-container {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  height: 100vh;
  background-size: cover;
  overflow: hidden;
}

.background-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(70deg, rgb(197, 197, 201), rgb(113, 223, 235));
  z-index: 1;
}

.login-card {
  position: relative;
  z-index: 2;
  width: 400px;
  padding: 20px;
  transition: transform 0.3s, opacity 0.3s;
  opacity: 0;
  transform: translateY(-20px);
  animation: fadeIn 0.5s forwards;
}

.login-title {
  text-align: center;
  margin-bottom: 20px;
  color: #fff;
}

@keyframes fadeIn {
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.el-input__inner {
  background: rgba(241, 239, 239, 0.2);
  border: none;
  color: #fff;
}

.el-input__inner::placeholder {
  color: #ddd;
}

.el-button {
  width: 100%;
}

.el-card {
  background: rgba(255, 255, 255, 0.1);
  border-radius: 10px;
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.5);
}
</style>