<template>
  <div class="tech container">
    <!-- 标题区 -->
    <header class="head">
      <h1 class="title">{{ fmt(current.name) }}</h1>
      <p class="subtitle" v-if="current.subtitle">{{ fmt(current.subtitle) }}</p>
      <p class="meta" v-if="current.meta">
        <span v-if="current.meta.author">作者：{{ fmt(current.meta.author) }}</span>
        <span v-if="current.meta.org">｜单位：{{ fmt(current.meta.org) }}</span>
        <span v-if="current.meta.date">｜更新：{{ current.meta.date }}</span>
      </p>
    </header>

    <!-- 章节：自动编号 1) 2) 3)… -->
    <div class="sections" role="document">
      <!-- 1) 项目背景（多段） -->
      <section class="sec numbered" v-if="overviewParas.length">
        <h2 class="sec-title">项目背景</h2>
        <p class="para" v-for="(p, i) in overviewParas" :key="'ov-'+i">{{ fmt(p) }}</p>
      </section>

      <!-- 2) 工艺原理：多组；每组=说明 + 公式（图/文本） -->
      <section class="sec numbered" v-if="hasPrincipleSection">
        <h2 class="sec-title">工艺原理</h2>
        <div class="principle-block" v-for="(b, i) in principleBlocks" :key="'pb-'+i">
          <p class="para" v-if="b.text">{{ fmt(b.text) }}</p>
          <figure class="equation" v-if="b.equationImg || b.equation">
            <img v-if="b.equationImg" :src="b.equationImg" alt="reaction" />
            <div v-else class="eq-text">{{ fmt(b.equation) }}</div>
          </figure>
        </div>
      </section>

      <!-- 3) 技术优势 -->
      <section class="sec numbered" v-if="advBlocks.length">
        <h2 class="sec-title">技术优势</h2>
        <ol class="adv-list">
          <li v-for="(b, i) in advBlocks" :key="'adv-'+i">
            <div class="adv-item">
              <div class="adv-head">
                <span class="adv-no">({{ i+1 }})</span>
                <span v-if="b.title" class="adv-title">{{ fmt(b.title) }}</span>
              </div>
              <div class="adv-body">
                <p class="para" v-for="(p, j) in b.paragraphs" :key="'p-'+j">{{ fmt(p) }}</p>

                <!-- 单图 -->
                <figure v-if="b.image" class="adv-figure">
                  <img :src="b.image" alt="" />
                </figure>

                <!-- 多图 -->
                <div v-if="b.images && b.images.length" class="adv-figure-grid">
                  <figure v-for="(src, k) in b.images" :key="'img-'+k" class="adv-figure">
                    <img :src="src" alt="" />
                  </figure>
                </div>
                <div v-if="b.caption" class="adv-cap">{{ fmt(b.caption) }}</div>
              </div>
            </div>
          </li>
        </ol>
      </section>

      <!-- 4) 经济效益：支持“标题 + 段落(无圆点)”或“标题 + 条目” -->
      <section class="sec numbered" v-if="economicIntro || economicBlocks.length">
        <h2 class="sec-title">经济效益</h2>

        <!-- 不编号的总领句 -->
        <p class="para" v-if="economicIntro">{{ fmt(economicIntro) }}</p>

        <ol class="eco-list" v-if="economicBlocks.length">
          <li v-for="(g, i) in economicBlocks" :key="'eco-g-'+i">
            <div class="eco-item">
              <div class="eco-head">
                <span class="eco-no">({{ i+1 }})</span>
                <span class="eco-title" v-if="g.title">{{ fmt(g.title) }}</span>
              </div>

              <!-- A) 直接正文：一段或多段（无圆点） -->
              <div v-if="g.paras && g.paras.length" class="eco-paras">
                <p class="para" v-for="(p, j) in g.paras" :key="'eco-p-'+j">{{ fmt(p) }}</p>
              </div>

              <!-- B) 二级条目列表（需要圆点时才出现） -->
              <ul class="eco-items" v-if="!g.paras?.length && g.items && g.items.length">
                <li v-for="(it, j) in g.items" :key="'eco-i-'+j">
                  <template v-if="typeof it === 'string'">
                    <span class="eco-item-text">{{ fmt(it) }}</span>
                  </template>
                  <template v-else>
                    <div class="eco-item-row">
                      <span class="eco-item-label" v-if="it.label">{{ fmt(it.label) }}：</span>
                      <span class="eco-item-text" v-if="it.text">{{ fmt(it.text) }}</span>
                    </div>
                    <ul class="eco-sub" v-if="Array.isArray(it.points) && it.points.length">
                      <li v-for="(p, k) in it.points" :key="'eco-pt-'+k">{{ fmt(p) }}</li>
                    </ul>
                  </template>
                </li>
              </ul>
            </div>
          </li>
        </ol>
      </section>

      <!-- 5) 成熟度 -->
      <section class="sec numbered" v-if="current.maturity">
        <h2 class="sec-title">成熟度</h2>
        <p class="para">{{ fmt(current.maturity) }}</p>
      </section>

      <!-- 6) 合作方式 -->
      <section class="sec numbered" v-if="current.cooperation && current.cooperation.length">
        <h2 class="sec-title">合作方式</h2>
        <ul class="bullets">
          <li v-for="(c, i) in current.cooperation" :key="`co-${i}`">{{ fmt(c) }}</li>
        </ul>
      </section>
    </div>

    <!-- 上/下一条 -->
    <!-- <nav class="pager">
      <button :disabled="!prevItem" @click="go(prevItem?.id)">上一条</button>
      <button :disabled="!nextItem" @click="go(nextItem?.id)">下一条</button>
    </nav> -->
  </div>
</template>

<script>
import { techItems } from '../../data/tech-items.js'
import { formatUnits } from '@/utils/chem-format.js'

export default {
  name: 'TechDetailPretty',
  data () { return { items: techItems } },
  computed: {
    currentId () { return String(this.$route?.params?.id || this.$route?.query?.id || this.$attrs.id || '2') },
    index () { const i = this.items.findIndex(x => x.id === this.currentId); return i === -1 ? 0 : i },
    current () { return this.items[this.index] },
    prevItem () { return this.items[this.index - 1] || null },
    nextItem () { return this.items[this.index + 1] || null },

    /* 项目背景：字符串/数组 → 多段 */
    overviewParas () {
      const o = this.current?.overview
      if (!o) return []
      if (typeof o === 'string') {
        const parts = o.split(/\r?\n\r?\n/).map(s => s.trim()).filter(Boolean)
        if (parts.length) return parts
        return o.split(/\r?\n/).map(s => s.trim()).filter(Boolean)
      }
      if (Array.isArray(o)) return o.map(s => String(s)).filter(Boolean)
      return []
    },

    /* 工艺原理：多组；优先 principles；兼容旧字段；兜底 flows */
    principleBlocks () {
      const c = this.current || {}
      if (Array.isArray(c.principles) && c.principles.length) {
        return c.principles.map(p => ({
          text: p.text || '',
          equation: p.equation || '',
          equationImg: p.equationImg || ''
        }))
      }
      const text = c.principle || ''
      const eq = c.equation || ''
      const eqImg = c.equationImg || ''
      if (text || eq || eqImg) return [{ text, equation: eq, equationImg: eqImg }]
      if (Array.isArray(c.flows) && c.flows.length) return [{ text: c.flows.join(' → ') }]
      return []
    },
    hasPrincipleSection () { return this.principleBlocks.length > 0 },

    /* 技术优势：对象数组/字符串数组兼容；支持段落 + 图片 */
    advBlocks () {
      const adv = this.current?.advantages ?? []
      if (!Array.isArray(adv) || adv.length === 0) return []
      const isObjectArray = adv.length && adv[0] !== null && typeof adv[0] === 'object' && !Array.isArray(adv[0])
      if (isObjectArray) {
        return adv.map(x => {
          const paragraphs = Array.isArray(x.paragraphs)
            ? x.paragraphs.filter(Boolean).map(String)
            : (x.paragraphs ? [String(x.paragraphs)] : (x.text ? [String(x.text)] : []))
          const images = Array.isArray(x.images) ? x.images : null
          const image  = images ? '' : (x.image || x.img || x.pic || '')
          return { title: x.title || '', paragraphs, image, images, caption: x.caption || x.cap || '' }
        })
      }
      return adv.map(s => ({ title: '', paragraphs: [String(s)], image: '', images: null, caption: '' }))
    },

    /* 经济效益：intro + 分组（分组可直接是“标题 + 段落”，无圆点） */
    economicIntro () {
      const c = this.current || {}
      if (typeof c.economicIntro === 'string' && c.economicIntro.trim()) return c.economicIntro.trim()
      const e = c.economic
      if (e && typeof e === 'object' && !Array.isArray(e)) {
        const cand = e.intro || e.summary || e.overview || e._intro
        if (typeof cand === 'string' && cand.trim()) return cand.trim()
      }
      return ''
    },
    economicBlocks () {
      const e = this.current?.economic
      if (!e) return []

      // 字典对象：key -> 分组；值可为 string / string[] / {text/items}
      if (e && typeof e === 'object' && !Array.isArray(e)) {
        const groups = []
        for (const key of Object.keys(e)) {
          if (['intro', 'summary', 'overview', '_intro'].includes(key)) continue
          const val = e[key]
          let paras = []
          let items = []
          if (typeof val === 'string') {
            paras = [val]
          } else if (Array.isArray(val)) {
            const hasObj = val.some(v => v && typeof v === 'object')
            if (hasObj) items = val
            else paras = val.map(String)
          } else if (val && typeof val === 'object') {
            if (val.text) paras = Array.isArray(val.text) ? val.text.map(String) : [String(val.text)]
            if (val.items) items = Array.isArray(val.items) ? val.items : [val.items]
          }
          groups.push({ title: key, paras, items })
        }
        return groups
      }

      // 数组里是“单键对象”：[{ '生产成本': '…' }, { '销售收入': '…' }]
      if (Array.isArray(e) && e.length && typeof e[0] === 'object' && !Array.isArray(e[0]) && !('title' in e[0])) {
        return e.map(obj => {
          const keys = Object.keys(obj || {})
          const title = keys[0] || ''
          const val = obj[title]
          let paras = []
          let items = []
          if (typeof val === 'string') {
            paras = [val]
          } else if (Array.isArray(val)) {
            const hasObj = val.some(v => v && typeof v === 'object')
            if (hasObj) items = val
            else paras = val.map(String)
          } else if (val && typeof val === 'object') {
            if (val.text) paras = Array.isArray(val.text) ? val.text.map(String) : [String(val.text)]
            if (val.items) items = Array.isArray(val.items) ? val.items : [val.items]
          }
          return { title, paras, items }
        })
      }

      // 新写法：[{ title, text?, items? }]
      if (Array.isArray(e) && e.length && typeof e[0] === 'object' && ('title' in e[0])) {
        return e.map(g => {
          const paras = g.text
            ? (Array.isArray(g.text) ? g.text.map(String) : [String(g.text)])
            : []
          const items = Array.isArray(g.items) ? g.items : (g.items ? [g.items] : [])
          return { title: g.title || '', paras, items }
        })
      }

      // 旧写法：string[]  => 每条作为“只有标题”的分组
      if (Array.isArray(e)) return e.map(s => ({ title: String(s), paras: [], items: [] }))
      if (typeof e === 'string') return [{ title: e, paras: [], items: [] }]
      return []
    }
  },
  methods: {
    fmt (s) { return formatUnits(s) },
    go (id) { if (this.$router) this.$router.push({ name: this.$route.name, params: { id } }) }
  }
}
</script>

<style scoped>
/* 版芯与排版 */
.container { max-width: 1120px; margin: 0 auto; padding: 32px 24px; color: #0f172a; }
.head { text-align: center; margin-bottom: 8px; }
.title { font-weight: 400; font-size: 42px; line-height: 1.2; margin: 0 0 10px; letter-spacing: .5px; }
.subtitle { color: #475569; margin: 0 0 6px; }
.meta { color: #64748b; font-size: 13px; }

/* 章节自动编号：1) 2) 3)… */
.sections { counter-reset: sec; margin-top: 8px; }
.sec { counter-increment: sec; margin-top: 28px; }
.sec-title { position: relative; font-size: 18px; font-weight: 700; padding-left: 36px; margin: 0 0 12px; }
.sec-title::before { content: counter(sec) ")"; position: absolute; left: 0; top: 0; font-weight: 700; color: #111827; }
.para { line-height: 1.95; font-size: 16px; color: #111827; }

/* 工艺原理：公式置中 */
.principle-block + .principle-block { margin-top: 16px; }
.equation { display: flex; justify-content: center; margin: 10px 0 0; }
.equation img { max-width: 80%; height: auto; }
.eq-text { font-family: "Times New Roman", STIXGeneral, serif; font-size: 24px; letter-spacing: .5px; }

/* 技术优势 */
.adv-list { list-style: none; margin: 0; padding: 0 0 0 28px; counter-reset: adv; }
.adv-list > li { counter-increment: adv; margin: 14px 0 18px; }
.adv-item { position: relative; }
.adv-head { display: flex; align-items: baseline; gap: 8px; font-size: 18px; }
.adv-no { font-weight: 400; color: #0f172a; margin-left: -28px; transform: translateX(-4px); display: inline-block; }
.adv-title { font-weight: 400; }
.adv-body { margin-top: 10px; }
.adv-body .para { margin: 0 0 8px; font-size: 16px; line-height: 1.95; }
.adv-figure { margin: 10px 0 0; text-align: center; }
.adv-figure img { max-width: 100%; height: auto; display: inline-block; }
.adv-cap { margin-top: 6px; font-size: 13px; color: #64748b; }
.adv-figure-grid { margin-top: 10px; display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 10px; align-items: start; }
.adv-figure-grid .adv-figure { margin: 0; }

/* 经济效益：分组 */
.eco-list { list-style: none; margin: 0; padding: 0; }
.eco-item { margin: 12px 0 16px; }
.eco-head { display: flex; align-items: baseline; gap: 8px; margin-bottom: 6px; }
.eco-no { font-weight: 400; color: #0f172a; }
.eco-title { font-weight: 400; font-size: 16px; color: #0f172a; }

/* 经济效益正文（无圆点） */
.eco-paras .para { margin: 0 0 8px; }

/* 仅当有条目时才显示圆点列表 */
.eco-items { margin: 0; padding-left: 26px; line-height: 1.9; }
.eco-item-row { display: block; }
.eco-item-label { color: #0f172a; }
.eco-item-text { color: #111827; }
.eco-sub { margin: 4px 0 8px 0; padding-left: 18px; list-style: disc; }

/* 翻页按钮 */
.pager { margin-top: 30px; display: flex; justify-content: center; gap: 12px; }
.pager button { padding: 8px 16px; border-radius: 8px; border: 1px solid #cbd5e1; background: #fff; cursor: pointer; }
.pager button:disabled { opacity: .5; cursor: not-allowed; }
</style>
