<template>
  <div>
    <!-- banner区 -->
    <div class="inner-banner">
      <div class="container">
        <div class="inner-title">
          <ul>
            <li><router-link to="/MapContainer">首页 >></router-link></li>
            <li>产品与技术 >></li>
            <li>典型装置</li>
          </ul>
        </div>
      </div>
    </div>
    <!-- 主要内容 -->
    <div class="my-tabs">
      <div class="alternating-layout">
        <div v-for="(item, index) in items" 
             :key="index" 
             class="item" 
             :class="{ 'reverse': index % 2 !== 0, 'hover-effect': hoveredIndex === index }"
             ref="items">
          <div class="image-container">
            <img :src="item.image" :alt="item.title" class="image">
          </div>
          <div class="text">
            <h3>{{ item.title }}</h3>
            <p>{{ item.description }}</p>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  data() {
    return {

      items: [
        {
          title: '6000吨/年三氯氧磷装置(全国首套连续化工艺) ',
          description:
            '该装置采用国内首套连续化生产工艺，设计生产能力达6000吨/年，主要生产三氯氧磷（POCl₃）。与传统间歇式工艺相比，连续化工艺的生产过程更为稳定，产品纯度更高，生产效率显著提升，同时具有安全性高、能耗低、环保优势明显的特点。',
          image: require("../../assets/images/HG/Device/image2-1.jpg")
        },
        {
          title: '2000吨/年烷氧基丙酸酯装置 ',
          description:
            '该装置生产能力为2000吨/年，主要用于生产烷氧基丙酸酯系列产品。烷氧基丙酸酯类产品常用于化妆品原料、表面活性剂、清洁剂以及工业助剂等领域。',
          image: require("../../assets/images/HG/Device/image2-2.jpg")
        },
        {
          title: '2.5万吨/年苄叉二氯装置(世界最大)',
          description:
            '该装置年产能力高达2.5万吨，是目前世界上产能规模最大的苄叉二氯（苄叉氯）生产装置。苄叉二氯广泛用于医药、农药、染料和精细化学品领域',
          image: require("../../assets/images/HG/Device/image2-3.jpg")
        },
        {
          title: '丙烯酸叔丁酯万吨级示范装置建设 （亚洲最大、世界第二）',
          description:
            '丙烯酸叔丁酯是高端涂料、油墨和胶粘剂的重要原料，该装置年产万吨级，是目前亚洲规模最大、世界第二大的丙烯酸叔丁酯生产示范项目。',
          image: require("../../assets/images/HG/Device/image2-4.jpg")
        },
        {
          title: '3.5万吨/年二苯胺装置(亚洲最大、世界最二)',
          description:
            '二苯胺广泛用于橡胶防老剂、染料中间体及特种精细化工领域。该装置规模达到3.5万吨/年，是目前亚洲产能最大的二苯胺装置，也是世界第二大的同类装置。装置技术成熟先进，具备生产连续性强、自动化程度高、产品质量稳定的优势。',
          image: require("../../assets/images/HG/Device/image2-5.jpg")
        },
        {
          title: '1.2万吨/年氯代苯甲醛装置',
          description:
            '绿氯代苯甲醛系列产品是医药、农药、染料的重要中间体。该装置年产能为1.2万吨。装置具备反应稳定性高、收率高、能耗低、环保友好等优势。',
          image: require("../../assets/images/HG/Device/image2-6.jpg")
        }
      ],
      hoveredIndex: null // 当前接近页面中心的item索引
    };
  },
  mounted() {
    window.addEventListener('scroll', this.handleScroll);
  },
  beforeDestroy() {
    window.removeEventListener('scroll', this.handleScroll);
  },
  methods: {
    handleScroll() {
      const centerY = window.innerHeight / 2; // 获取页面的垂直中心位置
      let closestIndex = null;
      let closestDistance = Infinity;

      this.$refs.items.forEach((item, index) => {
        const rect = item.getBoundingClientRect();
        const itemCenterY = rect.top + rect.height / 2;
        const distance = Math.abs(itemCenterY - centerY);

        if (distance < closestDistance) {
          closestIndex = index;
          closestDistance = distance;
        }
      });

      this.hoveredIndex = closestIndex; // 更新当前处于页面中心的item索引
    }
  }
};
</script>

<style scoped>
.my-tabs {
  width: 80%;
  margin-left: 10%;
  margin-top: 100px;
  margin-bottom: 100px;
}

.inner-banner {
  padding-top: 15px !important;
  width: 100% !important;
  height: 70px !important;
}

.inner-title {
  padding-top: 10px !important;
}

.alternating-layout {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.item {
  display: flex;
  align-items: center;
  gap: 20px;
  background-color: #fff; /* 卡片背景颜色 */
  padding: 20px; /* 卡片内边距 */
  border-radius: 10px; /* 圆角效果 */
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.5); /* 初始阴影 */
  transition: transform 0.3s ease, box-shadow 0.3s ease; /* 添加动画 */
  background-image: url('../../assets/images/clients-img/client-bg.png');
  background-size: 100%; /* 控制背景图片的尺寸 */
  background-repeat: repeat; /* 背景图片重复 */
}

.item:hover, .hover-effect {
  transform: scale(1.05); /* 放大效果 */
  box-shadow: 0 8px 16px rgba(0, 0, 0, 0.2); /* 阴影加深 */
}

.item img {
  width: 80%;
  margin-left: 10%;
  height: auto;
  border-radius: 8px;
}

.image-container {
  width: 50%;
}

.item .text {
  width: 50%;
}

.reverse {
  flex-direction: row-reverse;
}

.item h3 {
  margin-bottom: 0; /* 初始的 margin-bottom */
  transition: margin-bottom 1s ease, color 1s ease; /* 为 margin-bottom 和 color 设置过渡效果 */
}

.item:hover h3, .hover-effect h3 {
  color: #0f56d0;
  margin-bottom: 15px; /* 悬停时 margin-bottom 变化 */
}

.text p {
  margin: 0;
}

.item:hover p, .hover-effect p {
  color: #0f56d0;
  font-weight: bold;
}
</style>
