<template>
  <div>
    <!-- banner区 -->
    <div class="inner-banner">
      <div class="container">
        <div class="inner-title">
          <ul>
            <li><router-link to="/MapContainer">首页 >></router-link></li>
            <li>产品与技术 >></li>
            <li>高端产品</li>
          </ul>
        </div>
      </div>
    </div>
    <!-- 主要内容 -->
    <div class="my-tabs">
      <div class="alternating-layout">
        <div v-for="(item, index) in items" 
             :key="index" 
             class="item" 
             :class="{ 'reverse': index % 2 !== 0, 'hover-effect': hoveredIndex === index }"
             ref="items">
          <div class="image-container">
            <img :src="item.image" :alt="item.title" class="image">
          </div>
          <div class="text">
            <h3>{{ item.title }}</h3>
            <p>{{ item.description }}</p>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  data() {
    return {

      items: [
        {
          title: '洗舱站废气净化装置',
          description:
            '该装置针对化工储运过程中产生的洗舱废气，采用先进的吸收、吸附、催化氧化等组合工艺，能高效净化含VOCs（挥发性有机物）的废气，避免有害气体直接排放，确保装置满足环保排放标准。',
          image: require("../../assets/images/HG/Device/image1.png")
        },
        {
          title: '氯代芳香醛生产废气-液治理装置',
          description:
            '专门治理氯代芳香醛类生产过程中产生的含氯废气与废液，采用高效洗涤、中和、催化分解等联合处理技术，实现废气、废液中有毒有害氯化物的彻底转化或去除，显著降低环境风险。',
          image: require("../../assets/images/HG/Device/image2.png")
        },
        {
          title: '含氮芳香族废气净化装置',
          description:
            '针对染料、农药、医药中间体生产过程产生的含氮芳香族废气，采用催化氧化、化学吸附、生物降解等技术，能彻底去除含氮芳香族有机废气中的有害物质，保护环境和人员健康。',
          image: require("../../assets/images/HG/Device/image3.png")
        },
        {
          title: '环保清洁燃料技术',
          description:
            '该技术旨在研发和生产新型环保型清洁燃料，通过低硫、低氮、无重金属和无芳烃的配方设计及生产工艺优化，实现燃料燃烧过程中污染物排放大幅降低，助力行业节能减排目标的实现。',
          image: require("../../assets/images/HG/Device/image4.png")
        },
        {
          title: '含氯芳香族废气净化装置',
          description:
            '专门治理氯苯、氯甲苯、氯代烃类生产过程中产生的含氯芳香族废气，采用碱洗涤、活性炭吸附和催化氧化等组合技术，有效去除氯代芳香类有害废气，实现无害化处理。',
          image: require("../../assets/images/HG/Device/image5.png")
        },
        {
          title: '醇-醚生产废气-液治理装置',
          description:
            '针对醇醚类化工生产产生的有机废气及废液，采用冷凝回收、吸附吸收、催化燃烧等技术进行联合处理，实现废气和废液中有机物的高效回收利用或无害化转化，达到减排治污目的。',
          image: require("../../assets/images/HG/Device/image6.png")
        }
      ],
      hoveredIndex: null // 当前接近页面中心的item索引
    };
  },
  mounted() {
    window.addEventListener('scroll', this.handleScroll);
  },
  beforeDestroy() {
    window.removeEventListener('scroll', this.handleScroll);
  },
  methods: {
    handleScroll() {
      const centerY = window.innerHeight / 2; // 获取页面的垂直中心位置
      let closestIndex = null;
      let closestDistance = Infinity;

      this.$refs.items.forEach((item, index) => {
        const rect = item.getBoundingClientRect();
        const itemCenterY = rect.top + rect.height / 2;
        const distance = Math.abs(itemCenterY - centerY);

        if (distance < closestDistance) {
          closestIndex = index;
          closestDistance = distance;
        }
      });

      this.hoveredIndex = closestIndex; // 更新当前处于页面中心的item索引
    }
  }
};
</script>

<style scoped>
.my-tabs {
  width: 80%;
  margin-left: 10%;
  margin-top: 100px;
  margin-bottom: 100px;
}

.inner-banner {
  padding-top: 15px !important;
  width: 100% !important;
  height: 70px !important;
}

.inner-title {
  padding-top: 10px !important;
}

.alternating-layout {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.item {
  display: flex;
  align-items: center;
  gap: 20px;
  background-color: #fff; /* 卡片背景颜色 */
  padding: 20px; /* 卡片内边距 */
  border-radius: 10px; /* 圆角效果 */
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.5); /* 初始阴影 */
  transition: transform 0.3s ease, box-shadow 0.3s ease; /* 添加动画 */
  background-image: url('../../assets/images/clients-img/client-bg.png');
  background-size: 100%; /* 控制背景图片的尺寸 */
  background-repeat: repeat; /* 背景图片重复 */
}

.item:hover, .hover-effect {
  transform: scale(1.05); /* 放大效果 */
  box-shadow: 0 8px 16px rgba(0, 0, 0, 0.2); /* 阴影加深 */
}

.item img {
  width: 80%;
  margin-left: 10%;
  height: auto;
  border-radius: 8px;
}

.image-container {
  width: 50%;
}

.item .text {
  width: 50%;
}

.reverse {
  flex-direction: row-reverse;
}

.item h3 {
  margin-bottom: 0; /* 初始的 margin-bottom */
  transition: margin-bottom 1s ease, color 1s ease; /* 为 margin-bottom 和 color 设置过渡效果 */
}

.item:hover h3, .hover-effect h3 {
  color: #0f56d0;
  margin-bottom: 15px; /* 悬停时 margin-bottom 变化 */
}

.text p {
  margin: 0;
}

.item:hover p, .hover-effect p {
  color: #0f56d0;
  font-weight: bold;
}
</style>
