172.20.10.5:8090<template>
  <div>
    <!--联系我们大图-->
    <div class="inner-banner">
      <div class="container">
        <div class="inner-title">
          <ul>
            <li><router-link to="/MapContainer">首页>></router-link></li>
            <li>新闻动态>></li>
            <li>所内新闻</li>
          </ul>
        </div>
      </div>
    </div>

    <!-- 新闻列表 -->
    <div class="blog-area pt-100 pb-70">
      <div class="container">
        <div class="section-title text-center">
          <span class="sp-color2"></span>
          <h2>所内新闻</h2>
        </div>
        <div class="row pt-45">
          <div
            class="col-lg-4 col-md-6"
            style="cursor: pointer"
            v-for="(item, index) in nowdata"
            :key="index"
            @click="clickrouter(item.id)"
          >
            <div class="blog-card">
              <div class="blog-img">
                <div
                  style="
                    height: 300px;
                    justify-content: center;
                    text-align: center;
                  "
                >
                  <img :src="item.imgUrl" :alt="item.altText" />
                </div>
                <div class="blog-tag">
                  <h3>{{ item.createTime }}</h3>
                </div>
              </div>
              <div class="content" style="height: 150px">
                <ul>
                  <!-- <li><i class="bx"></i>国科提案社</li> -->
                  <!-- <li><router-link to="index.html"><i class='bx bx-purchase-tag-alt'></i>Business</router-link></li> -->
                </ul>
                <h3>
                  {{ item.newsNo }}
                </h3>
                <p
                  class="media-p"
                  style="
                    display: -webkit-box;
                    -webkit-box-orient: vertical;
                    -webkit-line-clamp: 2;
                    overflow: hidden;
                    text-overflow: ellipsis;
                    line-height: 1.5em; /* 每行的高度，根据需要调整 */
                    max-height: 3em; /* 2行的高度 */
                  "
                >
                  {{ item.title }}
                </p>
              </div>
            </div>
          </div>

          <!-- 分页器 -->
          <div class="col-lg-12 col-md-12 text-center pt-100">
            <div class="block">
              <el-pagination
                background
                @size-change="handleSizeChange"
                @current-change="handleCurrentChange"
                :current-page.sync="currentPage"
                :page-size="page_size"
                layout="prev, pager, next, jumper"
                :total="total"
              >
              </el-pagination>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>
<script>
export default {
  data() {
    return {
      currentPage: 1,
      page_size: 6,
      total: 1,
      nowdata: [],
      data: [],
      test_data: [],
    };
  },
  methods: {
    getData() {
      console.log(localStorage.getItem("token"))
      this.axios({
        url: "http://106.54.28.250:8093/news/queryNews",
        method: "post",
        headers: {
          token: localStorage.getItem("token"),
        },
        data: {
          newsType: "N001",
        },
      })
        .then((res) => {
          this.data = res.data.data;
          this.total = this.data.length;
          console.log("返回数据", this.data);
          // console.log("数据个数", this.total);
          this.pageData();
        })
        .catch((res) => {
          console.log(res);
        });
    },
    handleClose(done) {
      this.$confirm("确认关闭？")
        .then(() => {
          done();
        })
        .catch(() => {});
      // 这里是你想要自动运行的函数的代码
      this.total = this.data.length;
      // console.log("数据个数", this.total);
    },
    pageData() {
      var start = (this.currentPage - 1) * this.page_size;
      var end = Math.min(this.data.length, this.currentPage * this.page_size);
      this.nowdata = this.data.slice(start, end);
      // console.log("当前数据",this.nowdata)
    },
    handleSizeChange() {
      // console.log(`每页 ${val} 条`);
    },
    handleCurrentChange() {
      // console.log(`当前页: ${val}`);
      this.pageData();
    },
    clickrouter(event) {
      this.$router.push({ path: "/MediaDetail", query: { id: event } });
    },
  },
  mounted() {
    this.getData();
  },
};
</script>
<style scoped>
h3:hover {
  color: #ffc221;
}
</style>