<template>
  <div>
    <div v-if="showHeaderFooter">
      <HeadLogo style="height: 10vh; width: 100%; margin: 0px;"></HeadLogo>
      <div class="group">
        <LeftMenu v-if="showLeft"></LeftMenu>
        <router-view />
      </div>
    </div>
    <div v-else>
      <Header></Header>
      <router-view />
      <Footer></Footer>
    </div>
  </div>
</template>

<script>
import Header from "./pages/HeadTitle.vue";
import Footer from "./pages/FootTitle.vue";
import LeftMenu from "./pages/LeftMenu.vue";
import HeadLogo from "./pages/HeadLogo.vue";

export default {
  name: "App",
  components: {
    // HelloWorld,
    Header,
    Footer,
    LeftMenu,
    HeadLogo,
  },
  computed: {
    showHeaderFooter() {
      const hiddenRoutes = [
        "/LogoIn",
        "/AddNews",
        "/ControlNews",
        "/ControlMedia",
        "/ControlScience",
        "/ControlTrends",
      ];
      // 如果当前路由路径在隐藏列表中，则返回 false
      return hiddenRoutes.includes(this.$route.path);
    },
    showLeft() {
      const hiddenRoutes = ["/LogoIn"];
      // 如果当前路由路径在隐藏列表中，则返回 false
      return !hiddenRoutes.includes(this.$route.path);
    },
  },
  created() {
    this.$router.push("/MapContainer").catch((err) => err);
  },
};
</script>

