<template>
  <div class="Table">
    <div class="inner-banner">
      <div class="inner-title" style="padding: 30px">
        <el-page-header @back="goBack"  style="color: rgb(255, 255, 255)"
          :content-style="{ color: 'white' }">
          <template #content>
            <span style="color: white;">行业动态</span>
          </template>
        </el-page-header>
      </div>
    </div>
    <div class="Table-box">
      <div style="display: flex; margin-bottom: 10px">
        <el-button type="primary" @click="Add">添加文章</el-button>
        <el-input
          v-model="input"
          placeholder="请输入内容"
          style="width: 250px; margin-left: auto"
          @input="handleInput"
        ></el-input>
      </div>

      <div>
        <el-table :data="nowData" style="width: 100%" border>
          <el-table-column prop="title" label="标题"> </el-table-column>

          <el-table-column prop="newsNo" label="作者"> </el-table-column>
          <el-table-column prop="createTime" label="日期"> </el-table-column>
          <el-table-column fixed="right" label="操作" width="200">
            <template slot-scope="scope">
              <!-- <el-button @click="Modify(scope.row)" type="text" size="small"
                  >修改</el-button
                > -->
              <el-button type="text" size="small" @click="Delete(scope.row)"
                >删除</el-button
              >
              <el-button type="text" size="small" @click="Check(scope.row)"
                >查看</el-button
              >
            </template>
          </el-table-column>
        </el-table>
      </div>
      <div class="block" style="text-align: center">
        <el-pagination
          @current-change="handleCurrentChange"
          :current-page.sync="currentPage"
          :page-size="page_size"
          layout="total, prev, pager, next,jumper"
          :total="totalSize"
        >
          >
        </el-pagination>
      </div>
    </div>
    <div>
      <el-dialog title="文章信息" :visible.sync="dialogFormVisible" width="70%">
        <div>
          <el-form ref="form" :model="form" label-width="80px">
            <el-form-item label="文章名称:">
              <el-input clearable v-model="form.name"></el-input>
            </el-form-item>
            <el-form-item label="发布作者:">
              <el-input clearable v-model="form.author"></el-input>
            </el-form-item>
            <el-form-item label="添加封面:">
              <el-upload
                class="upload-demo"
                ref="upload"
                action=""
                :on-change="
                  (file) => {
                    change(file);
                  }
                "
                :on-remove="handleRemove"
                :file-list="form.fileList"
                :auto-upload="false"
                :limit="1"
                :on-exceed="handleExceed"
              >
                <el-button slot="trigger" size="small" type="primary"
                  >选取文件</el-button
                >
                <div slot="tip" class="el-upload__tip">
                  只能上传jpg/png文件，且不超过500kb
                </div>
              </el-upload>
            </el-form-item>

            <el-form-item label="链接url:">
              <el-input clearable v-model="form.link"></el-input>
            </el-form-item>
            <div style="text-align: center; margin: 20px 0px">
              <el-button type="primary" @click="onSubmit('N002')"
                >立即创建</el-button
              >
            </div>
          </el-form>
        </div>
      </el-dialog>
    </div>
  </div>
</template>
  <script>
import Vue from "vue";
export default Vue.extend({
  methods: {
    handleInput() {
      console.log("当前输入的内容是：", this.input);
      if (this.input != "") {
        this.axios({
          url: "http://106.54.28.250:8093/news/queryNews",
          method: "post",
          data: {
            title: this.input,
          },
        })
          .then((res) => {
            console.log(res);
            this.form.tableData = [];
            this.form.tableData = res.data.data;
            this.totalSize = this.form.tableData.length;
            this.currentPage = 1;
            console.log(this.form.tableData);
            this.pageData();
          })
          .catch((res) => {
            console.log(res);
          });
      }
    },
    getData() {
      this.axios({
        url: "http://106.54.28.250:8093/news/queryNews",
        method: "post",
        data: {
          newsType: "N002",
        },
      })
        .then((res) => {
          console.log(res);
          this.form.tableData = res.data.data;
          this.totalSize = this.form.tableData.length;
          this.currentPage = 1;
          this.pageData();
        })
        .catch((res) => {
          console.log(res);
        });
    },
    pageData() {
      var start = (this.currentPage - 1) * this.page_size;
      var end = Math.min(
        this.form.tableData.length,
        this.currentPage * this.page_size
      );
      this.nowData = this.form.tableData.slice(start, end);
    },
    handleCurrentChange() {
      this.pageData();
    },
    goBack() {
      this.$router.push("/MapContainer");
    },
    Delete(e) {
      console.log("删除", e.id);
      this.$confirm("此操作将永久删除该文件, 是否继续?", "提示", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning",
      })
        .then(() => {
          const _that = this;
          console.log("已发送请求");
          // 使用 axios 发送 POST 请求
          _that.axios
            .delete("http://106.54.28.250:8093/news/delNews?id=" + e.id, {
              headers: {
                "Content-Type": "multipart/form-data",
                token: localStorage.getItem("token"),
              },
            })
            .then(() => {
              this.$message({
                message: "删除成功",
                type: "success",
              });
              _that.getData();
            });
        })
        .catch(() => {
          this.$message({
            type: "info",
            message: "已取消删除",
          });
        });
    },
    Modify(e) {
      console.log("修改", e);
      this.AorM = 2;
      this.dialogFormVisible = true;
      this.form.html = e.content;
      this.form.author = e.newsNo;
      this.form.name = e.title;
    },
    Add() {
      console.log("添加");
      this.AorM = 1;
      this.form = this.template;
      this.dialogFormVisible = true;
    },
    Check(e) {
      console.log(e.id);
      this.$router.push({ path: "/MediaDetail", query: { id: e.id } });
    },
    change(file) {
      console.log(file);
      this.form.file = file;
    },

    handleRemove(file, fileList) {
      console.log(file, fileList);
      this.form.file = "";
      this.form.fileList = [];
    },
    handleExceed(files, fileList) {
      this.$message.warning(
        `当前限制选择 1 个文件，本次选择了 ${files.length} 个文件，共选择了 ${
          files.length + fileList.length
        } 个文件`
      );
    },

    onSubmit(type) {
      var e = this.form;
      var formData = new FormData();
      console.log(this.AorM);
      if (this.AorM == 1) {
        // 创建 FormData 对象
        formData.append("file", e.file.raw);
        formData.append("newsNo", e.author);
        formData.append("title", e.name);
        formData.append("content", e.html);
        formData.append("newsType", type);
        formData.append("link", e.link);
        // 使用 axios 发送 POST 请求
        this.axios
          .post("http://106.54.28.250:8093/news/addNews", formData, {
            headers: {
              "Content-Type": "multipart/form-data",
              token: localStorage.getItem("token"),
            },
          })
          .then(() => {
            this.dialogFormVisible = false;
            this.getData();
            this.$message({
              message: "添加成功",
              type: "success",
            });
            // this.$router.push({ path: "/MediaNews" });
          })
          .catch(() => {
            this.$message.error("添加失败");
          });
      } else {
        // 创建 FormData 对象
        formData.append("file", e.file.raw);
        formData.append("newsNo", e.author);
        formData.append("title", e.name);
        formData.append("content", e.html);
        formData.append("newsType", type);
        formData.append("link", e.link);
        // 使用 axios 发送 POST 请求
        this.axios
          .post("http://106.54.28.250:8093/news/editNews", formData, {
            headers: {
              "Content-Type": "application/json;charset=utf-8",
              token: localStorage.getItem("token"),
            },
          })
          .then((res) => {
            console.log(res);

            this.dialogFormVisible = false;
            this.getData();
            this.$message({
              message: "修改成功",
              type: "success",
            });
            // this.$router.push({ path: "/MediaNews" });
          })
          .catch(() => {
            this.$message.error("修改失败");
          });
      }
    },
  },
  mounted() {
    this.getData();
  },
  data() {
    return {
      template: {
        link: "",
        fileList: [],
        name: "",
        author: "",
        imageUrl: "",
        file: "",

        tableData: [],
      },
      form: {
        link: "",
        fileList: [],
        name: "",
        author: "",
        imageUrl: "",
        file: "",

        tableData: [],
      },
      data: [],
      nowData: [],
      currentPage: 1,
      totalSize: 1,
      page_size: 7,
      input: "",
      dialogFormVisible: false,
      AorM: 1,
    };
  },
});
</script>
<style scoped>
.inner-banner {
  background-color: #464646;
  border-radius: 5px;
}

.Table {
  width: 100%;
  height: 100%;
  background-color: #f1efef;
}
.Table-box {
  margin-top: 0.5%;
  height: 88%;
  width: 99%;
  padding: 20px 40px;
  border-radius: 15px;
  /* box-shadow: 1px 1px 2px 5px rgba(168, 168, 170, 0.2); */
  background-color: #ffffff;
}
.block {
  margin: 30px 0px;
}
</style>

  