import VueRouter from "vue-router";
import { jwtDecode } from 'jwt-decode'; // 使用命名导出
import Vue from 'vue';

Vue.use(VueRouter);

// 修复重复导航报错问题
const RouterPush = VueRouter.prototype.push;
VueRouter.prototype.push = function push(to) {
  return RouterPush.call(this, to).catch(err => err);
};
const RouterReplace = VueRouter.prototype.replace;
VueRouter.prototype.replace = function replace(to) {
  return RouterReplace.call(this, to).catch(err => err);
};

// 引入页面组件
import MapContainer from '../pages/MapContainer.vue';
import ConTact from "../pages/ConTact.vue";
import MediaAttention from "@/pages/MediaAttention.vue";
import SocialImpactDetail from "@/pages/SocialImpactDetail.vue";
import AboutWe from "../pages/About/AboutWe.vue";
import AbCollege from "../pages/About/AbCollege.vue";
import AbMember from "../pages/About/AbMember.vue";
import AbOrganizational from "../pages/About/AbOrganizational.vue";
import PopularScience from '../pages/News/PopularScience.vue';
import ResearchTrends from '../pages/News/ResearchTrends.vue';
import MediaNews from '../pages/News/MediaNews.vue';
import MediaDetail from '../pages/News/MediaDetail.vue';
import TechAll from "@/pages/Techonlogy/TechAll.vue";
import TeProduvte from "@/pages/Techonlogy/TeProduvte.vue";
import TeDevices from "@/pages/Techonlogy/TeDevices.vue";
import TeCases from "@/pages/Techonlogy/TeCases.vue";
import TechDetail from "../pages/Techonlogy/TechDetail.vue";
import ScientificAchive from "../pages/Scientific/ScientificAchive.vue";
import ScientificField from "../pages/Scientific/ScientificField.vue";
import AcadeJournals from "../pages/Scientific/AcadeJournals.vue";
import IntellectProperty from "../pages/Scientific/IntellectProperty.vue";
import ScientificInnovation from "../pages/Scientific/ScientificInnovation.vue";
import LogoIn from "@/pages/Administration/LogoIn.vue";
import AddNews from "@/pages/Administration/AddNews.vue";
import ControlNews from "@/pages/Administration/ControlNews.vue";
import ControlMedia from '@/pages/Administration/ControlMedia.vue';
import ControlScience from '@/pages/Administration/ControlScience.vue';
import ControlTrends from '@/pages/Administration/ControlTrends.vue';
import MyTest from "@/pages/About/MyTest.vue";
import WangTest from "@/pages/News/WangTest.vue";

const router = new VueRouter({
    routes: [
        { path: '/MapContainer', component: MapContainer },
        { path: '/MediaNews', component: MediaNews },
        { path: '/MediaDetail', component: MediaDetail },
        { path: '/PopularScience', component: PopularScience },
        { path: '/ResearchTrends', component: ResearchTrends },
        { path: '/AboutWe', component: AboutWe },
        { path: '/TechAll', component: TechAll },
        { path: '/ConTact', component: ConTact },
        { path: '/ScientificAchive', component: ScientificAchive },
        { path: '/ScientificField', component: ScientificField },
        { path: '/AcadeJournals', component: AcadeJournals },
        { path: '/IntellectProperty', component: IntellectProperty },
        { path: '/TechDetail', component: TechDetail },
        { path: '/ScientificInnovation', component: ScientificInnovation },
        { path: '/AbCollege', component: AbCollege },
        { path: '/AbOrganizational', component: AbOrganizational },
        { path: '/AbMember', component: AbMember },
        { path: '/TeDevices', component: TeDevices },
        { path: '/TeCases', component: TeCases },
        { path: '/MediaAttention', component: MediaAttention },
        {
            path: '/SocialImpactDetail/:id',
            name: 'social-impact-detail',
            component: SocialImpactDetail
        },
        { path: '/TeProduvte', component: TeProduvte },
        { path: '/AddNews', component: AddNews },
        { path: '/LogoIn', component: LogoIn },
        { 
            path: '/ControlNews', 
            component: ControlNews,
            meta: { requiresAuth: true }
        },
        { 
            path: '/ControlMedia', 
            component: ControlMedia,
            meta: { requiresAuth: true }
        },
        { 
            path: '/ControlScience', 
            component: ControlScience,
            meta: { requiresAuth: true }
        },
        { 
            path: '/ControlTrends', 
            component: ControlTrends,
            meta: { requiresAuth: true }
        },
        { path: '/MyTest', component: MyTest },
        { path: '/WangTest', component: WangTest }
    ],
    scrollBehavior() {
        return { x: 0, y: 0 };
    }
});
// 判断 token 是否过期的函数
function isTokenExpired(token) {
    try {
      const decoded = jwtDecode(token); // 解析 token
      if (decoded.exp * 1000 < Date.now()) {
        // Token 已经过期
        return true;
      } else {
        // Token 仍然有效
        return false;
      }
    } catch (error) {
      console.error("Invalid token", error);
      return true; // 如果 token 解析失败，假定 token 已经过期
    }
  }

// 路由守卫：检查token
router.beforeEach((to, from, next) => {
  if (to.matched.some(record => record.meta.requiresAuth)) {
    const token = localStorage.getItem('token');
    if (!token) {
      // 提示用户需要登录
      alert('您需要登录才能访问该页面。');
      // 重定向到登录页面
      next({
        path: '/LogoIn',
        query: { redirect: to.fullPath }
      });
    } else {
      // 检查token是否过期，假设我们在localStorage中保存了token过期时间
      
      if (isTokenExpired(token)) {
        // 提示用户需要重新登录
        alert('您的登录信息已过期，请重新登录。');
        // token已过期
        localStorage.removeItem('token');
        next({
          path: '/LogoIn',
          query: { redirect: to.fullPath }
        });
      } else {
        // token有效
        next();
      }
    }
  } else {
    // 不需要验证的路由直接进入
    next();
  }
});

export default router;
