            <div>
              <el-form ref="form" :model="form2" label-width="80px">
                <el-form-item label="文章名称:">
                  <el-input clearable v-model="form2.name"></el-input>
                </el-form-item>
                <el-form-item label="发布作者:">
                  <el-input clearable v-model="form2.author"></el-input>
                </el-form-item>

                <el-form-item label="添加封面:">
                  <el-upload
                    class="upload-demo"
                    ref="upload"
                    action=""
                    :on-change="
                      (file) => {
                        change(file, 'N002');
                      }
                    "
                    :on-remove="handleRemove"
                    :file-list="form2.fileList"
                    :auto-upload="false"
                    :limit="1"
                    :on-exceed="handleExceed"
                  >
                    <el-button slot="trigger" size="small" type="primary"
                      >选取文件</el-button
                    >
                    <div slot="tip" class="el-upload__tip">
                      只能上传jpg/png文件，且不超过500kb
                    </div>
                  </el-upload>
                </el-form-item>

                <!-- <el-form-item label="文章内容">
                  <el-input type="textarea" v-model="form.desc"></el-input>
                </el-form-item> -->

                <div style="border: 1px solid #ccc">
                  <Toolbar
                    style="border-bottom: 1px solid #ccc"
                    :editor="form2.editor"
                    :defaultConfig="form2.toolbarConfig"
                    :mode="form2.mode"
                  />
                  <Editor
                    style="height: 500px; overflow-y: hidden"
                    v-model="form2.html"
                    :defaultConfig="form2.editorConfig"
                    :mode="form2.mode"
                    @onCreated="onCreated2"
                  />
                </div>

                <div style="text-align: center; margin: 50px 0px">
                  <el-button type="primary" @click="onSubmit('N002')"
                    >立即创建</el-button
                  >
                </div>
              </el-form>
              <el-table
                :data="form2.tableData"
                style="width: 100%"
