                  </template>
                </el-table-column>
              </el-table>
            </div>
          </div>
        </el-tab-pane>
        <el-tab-pane label="行业动态"
          ><div class="margin_left_10">
            <h1>行业动态</h1>
            <div>
              <el-form ref="form" :model="form3" label-width="80px">
                <el-form-item label="文章名称:">
                  <el-input clearable v-model="form3.name"></el-input>
                </el-form-item>
                <el-form-item label="发布作者:">
                  <el-input clearable v-model="form3.author"></el-input>
                </el-form-item>

                <el-form-item label="添加封面:">
                  <el-upload
                    class="upload-demo"
                    ref="upload"
                    action=""
                    :on-change="
                      (file) => {
                        change(file, 'N003');
                      }
                    "
                    :on-remove="handleRemove"
                    :file-list="form3.fileList"
                    :auto-upload="false"
                    :limit="1"
                    :on-exceed="handleExceed"
                  >
                    <el-button slot="trigger" size="small" type="primary"
                      >选取文件</el-button
                    >
                    <div slot="tip" class="el-upload__tip">
