                    </div>
                  </el-upload>
                </el-form-item>
                <el-form-item label="链接url:">
                  <el-input clearable v-model="form3.link"></el-input>
                </el-form-item>

                <div style="text-align: center; margin: 50px 0px">
                  <el-button type="primary" @click="onSubmit('N003')"
                    >立即创建</el-button
                  >
                </div>
              </el-form>
              <el-table
                :data="form3.tableData"
                style="width: 100%"
                max-height="300"
              >
                <el-table-column prop="link" label="链接" width="120">
                </el-table-column>
                <el-table-column prop="newsNo" label="作者" width="120">
                </el-table-column>
                <el-table-column prop="title" label="标题"> </el-table-column>
                <el-table-column fixed="right" label="操作" width="100">
                  <template slot-scope="scope">
                    <el-button
                      @click="Check(scope.row)"
                      type="text"
                      size="small"
                      >查看</el-button
                    >
