</template>
<script>
import Vue from "vue";
import { Editor, Toolbar } from "@wangeditor/editor-for-vue";
export default Vue.extend({
  components: { Editor, Toolbar },

  data() {
    return {
      default: {
        link: "",
        fileList: [],
        name: "",
        author: "",
        date1: "",
        imageUrl: "",
        file: "",
        editor: null,
        html: "<p></p>",
        toolbarConfig: {},
        editorConfig: { placeholder: "请输入内容..." },
        mode: "default",
        tableData: [],
      },
      form: {
        link: "",
        fileList: [],
        name: "",
        author: "",
        date1: "",
        imageUrl: "",
        file: "",
        editor: null,
        html: "<p></p>",
        toolbarConfig: {},
        editorConfig: { placeholder: "请输入内容..." },
        mode: "default",
        tableData: [],
      },
      form2: {
        link: "",
        fileList: [],
        name: "",
        author: "",
        date1: "",
        imageUrl: "",
        editor: null,
        html: "<p></p>",
        toolbarConfig: {},
        editorConfig: { placeholder: "请输入内容..." },
        mode: "default", // or 'simple'
        tableData: [],
      },
      form3: {
        link: "",
        fileList: [],
        name: "",
        author: "",
        date1: "",
        imageUrl: "",
        editor: null,
        html: "<p></p>",
        toolbarConfig: {},
        editorConfig: { placeholder: "请输入内容..." },
        mode: "default", // or 'simple'
        tableData: [],
      },
    };
  },
  methods: {
    change(file, type) {
      console.log(file);
      if (type == "N001") {
        this.form.file = file;
      } else if (type == "N002") {
        this.form2.file = file;
      } else {
        this.form3.file = file;
      }
    },
    handleRemove(file, fileList) {
      console.log(file, fileList);
      this.form.file = "";
      this.form2.file = "";
      this.form3.file = "";
      this.form.fileList = [];
      this.form2.fileList = [];
      this.form3.fileList = [];
    },
    handleExceed(files, fileList) {
      this.$message.warning(
        `当前限制选择 1 个文件，本次选择了 ${files.length} 个文件，共选择了 ${
          files.length + fileList.length
        } 个文件`
      );
    },
    onSubmit(type) {
      var e = this.form;
      if (type == "N002") {
        e = this.form2;
      }
      if (type == "N003") {
        e = this.form3;
      }
      console.log("e", e);
      const axios = require("axios");

      // 创建 FormData 对象
      var formData = new FormData();
      formData.append("file", e.file.raw);
      formData.append("newsNo", e.author);
      formData.append("title", e.name);
      formData.append("content", e.html);
      formData.append("newsType", type);
      formData.append("createTime", e.date1);
      formData.append("link", e.link);

      // 使用 axios 发送 POST 请求
      axios
        .post("http://106.54.28.250:8093/news/addNews", formData, {
          headers: {
            "Content-Type": "multipart/form-data",
          },
        })
        .then(() => {
          this.$message({
            message: "添加成功",
            type: "success",
          });
          if (type == "N001") {
            this.$router.push({ path: "/MediaNews" });
          }
          if (type == "N002") {
            this.$router.push({ path: "/ResearchTrends" });
          }
          if (type == "N003") {
            this.$router.push({ path: "/PopularScience" });
          }
        })
        .catch(() => {
          this.$message.error("添加失败");
        });
    },
    onCreated1(editor) {
      this.form.editor = Object.seal(editor); // 一定要用 Object.seal() ，否则会报错
    },
    onCreated2(editor) {
      this.form2.editor = Object.seal(editor); // 一定要用 Object.seal() ，否则会报错
    },
    beforeDestroy() {
      const editor = this.editor;
      if (editor == null) return;
      editor.destroy(); // 组件销毁时，及时销毁编辑器
    },
    GetData() {
      this.Getform1();
      this.Getform2();
      this.Getform3();
    },
    Getform1() {
      this.axios({
        url: "http://106.54.28.250:8093/news/queryNews",
        method: "post",
        data: {
          newsType: "N001",
        },
      })
        .then((res) => {
          this.form.tableData = [];
          this.form.tableData = res.data.data;
          console.log("返回数据", this.form.tableData);
          // console.log("数据个数", this.total);
        })
        .catch((res) => {
          console.log(res);
        });
    },
    Getform2() {
      this.axios({
        url: "http://106.54.28.250:8093/news/queryNews",
        method: "post",
        data: {
          newsType: "N002",
        },
      })
        .then((res) => {
          this.form2.tableData = [];
          this.form2.tableData = res.data.data;
          console.log("返回数据", this.form2.tableData);
          // console.log("数据个数", this.total);
        })
        .catch((res) => {
          console.log(res);
        });
    },
    Getform3() {
      this.axios({
        url: "http://106.54.28.250:8093/news/queryNews",
        method: "post",
        data: {
          newsType: "N003",
        },
      })
        .then((res) => {
          this.form3.tableData = [];
          this.form3.tableData = res.data.data;
          console.log("返回数据", this.form3.tableData);
          // console.log("数据个数", this.total);
        })
        .catch((res) => {
          console.log(res);
        });
    },
    Delete(res) {
      console.log("删除", res.id);
      const axios = require("axios");

      console.log("已发送请求");
      // 使用 axios 发送 POST 请求
      axios
        .delete("http://106.54.28.250:8093/news/delNews?id=" + res.id, {
          headers: {
            "Content-Type": "multipart/form-data",
          },
        })
        .then(() => {
          this.$message({
            message: "删除成功",
            type: "success",
          });
          this.GetData();
        })
        .catch(() => {
          this.$message.error("删除失败");
        });
    },
    Check(res) {
      console.log("查看", res);
      this.$router.push({ path: "/MediaDetail", query: { id: res.id } });
    },
  },
  mounted() {
    this.GetData();
  },
});
</script>
