<template>
  <div>
    <!-- banner区 -->
    <div class="inner-banner">
      <div class="container">
        <div class="inner-title">
          <ul>
            <li><router-link to="/MapContainer">首页 >></router-link></li>
            <li>产品与技术 >></li>
            <li>应用案例</li>
          </ul>
        </div>
      </div>
    </div>
    <!-- 主要内容 -->
    <div class="my-tabs">
      <div class="alternating-layout">
        <div v-for="(item, index) in items" :key="index" class="item"
          :class="{ 'reverse': index % 2 !== 0, 'hover-effect': hoveredIndex === index }" ref="items">
          <div class="image-container">
            <img :src="item.image" :alt="item.title" class="image">
          </div>
          <div class="text">
            <h3>{{ item.title }}</h3>
            <p>{{ item.description }}</p>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  data() {
    return {

      items: [
        {
          title: '表彰与感谢——合作共赢的里程碑',
          description:
            '中盐常州化工股份有限公司送喜报,全流程绿色智能制造工艺,近3年为公司创造了3亿元以上的经济效益',
          image: require("../../assets/images/HG/TaCases/1.jpg")
        },
        {
          title: '签约仪式',
          description:
            '全省化工产业安全环保整治提升暨安全生产专项整治工作签约仪式',
          image: require("../../assets/images/HG/TaCases/3.png")
        },
        {
          title: '表彰与感谢——合作共赢的里程碑',
          description:
            '中盐常州化工股份有限公司送喜报,全流程绿色智能制造工艺,近3年为公司创造了3亿元以上的经济效益',
          image: require("../../assets/images/HG/TaCases/4.jpg")
        },

      ],
      hoveredIndex: null // 当前接近页面中心的item索引
    };
  },
  mounted() {
    window.addEventListener('scroll', this.handleScroll);
  },
  beforeDestroy() {
    window.removeEventListener('scroll', this.handleScroll);
  },
  methods: {
    handleScroll() {
      const centerY = window.innerHeight / 2; // 获取页面的垂直中心位置
      let closestIndex = null;
      let closestDistance = Infinity;

      this.$refs.items.forEach((item, index) => {
        const rect = item.getBoundingClientRect();
        const itemCenterY = rect.top + rect.height / 2;
        const distance = Math.abs(itemCenterY - centerY);

        if (distance < closestDistance) {
          closestIndex = index;
          closestDistance = distance;
        }
      });

      this.hoveredIndex = closestIndex; // 更新当前处于页面中心的item索引
    }
  }
};
</script>

<style scoped>
.my-tabs {
  width: 80%;
  margin-left: 10%;
  margin-top: 100px;
  margin-bottom: 100px;
}

.inner-banner {
  padding-top: 15px !important;
  width: 100% !important;
  height: 70px !important;
}

.inner-title {
  padding-top: 10px !important;
}

.alternating-layout {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.item {
  display: flex;
  align-items: center;
  gap: 20px;
  background-color: #fff;
  /* 卡片背景颜色 */
  padding: 20px;
  /* 卡片内边距 */
  border-radius: 10px;
  /* 圆角效果 */
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.5);
  /* 初始阴影 */
  transition: transform 0.3s ease, box-shadow 0.3s ease;
  /* 添加动画 */
  background-image: url('../../assets/images/clients-img/client-bg.png');
  background-size: 100%;
  /* 控制背景图片的尺寸 */
  background-repeat: repeat;
  /* 背景图片重复 */
}

.item:hover,
.hover-effect {
  transform: scale(1.05);
  /* 放大效果 */
  box-shadow: 0 8px 16px rgba(0, 0, 0, 0.2);
  /* 阴影加深 */
}

.item img {
  width: 80%;
  margin-left: 10%;
  height: auto;
  border-radius: 8px;
}

.image-container {
  width: 50%;
}

.item .text {
  width: 50%;
}

.reverse {
  flex-direction: row-reverse;
}

.item h3 {
  margin-bottom: 0;
  /* 初始的 margin-bottom */
  transition: margin-bottom 1s ease, color 1s ease;
  /* 为 margin-bottom 和 color 设置过渡效果 */
}

.item:hover h3,
.hover-effect h3 {
  color: #0f56d0;
  margin-bottom: 15px;
  /* 悬停时 margin-bottom 变化 */
}

.text p {
  margin: 0;
}

.item:hover p,
.hover-effect p {
  color: #0f56d0;
  font-weight: bold;
}
</style>
