// src/utils/chem-format.js
const SUP = { '0':'⁰','1':'¹','2':'²','3':'³','4':'⁴','5':'⁵','6':'⁶','7':'⁷','8':'⁸','9':'⁹','+':'⁺','-':'⁻','(':'⁽',')':'⁾' };
const SUB = { '0':'₀','1':'₁','2':'₂','3':'₃','4':'₄','5':'₅','6':'₆','7':'₇','8':'₈','9':'₉','+':'₊','-':'₋','(':'₍',')':'₎','x':'ₓ','X':'ₓ' };
const toSup = s => String(s).split('').map(c => SUP[c] || c).join('');
const toSub = s => String(s).split('').map(c => SUB[c] || c).join('');

export function formatUnits(input) {
  if (input == null) return '';
  let str = String(input);

  // 1) caret 指数：10^6、h^-1、m^3 …
  str = str.replace(/\^([+\-\d()]+)/g, (_, exp) => toSup(exp));

  // 2) 常见 “单位^-n” 紧贴写法（含 30000h-1 这种）
  str = str.replace(/\b(h|s|min|m|L|mol|Pa|W|K)-(\d+)\b/gi, (_, u, n) => u + toSup('-' + n));
  str = str.replace(/h-(\d+)/gi, (_, n) => 'h' + toSup('-' + n));

  // 3) 体积单位与浓度
  str = str.replace(/\bm3\b/g, 'm' + toSup('3'));
  str = str.replace(/\/m3\b/g, '/m' + toSup('3'));
  str = str.replace(/([µμu]?g|g|kg|mg)\/m3\b/gi, (_, u) => u + '/m' + toSup('3'));

  // 4) 化学式下标（更宽松，不依赖 \b；覆盖 CO2 / C6H14O2 / Fe2O3 等）
  //    逐段匹配 “元素(1~2字母) + 数字(>=1位)”；全局替换，允许中文/标点紧邻
  str = str.replace(/([A-Za-z][a-z]?)(\d+)/g, (_, sym, num) => sym + toSub(num));

  // 5) NOx / SOx（x 下标），大小写都处理
  str = str.replace(/\b([A-Z]{1,2})[xX]\b/g, (_, sym) => sym + SUB['x']);

  // 6) PM2.5：把 2 变下标
  str = str.replace(/\bPM(\d+)\.(\d+)\b/g, (_, a, b) => 'PM' + toSub(a) + '.' + b);

  return str;
}
